SELECT COUNT(*)
FROM blog_comment
WHERE article_id = #{article}
  AND parent_id IS NULL
  AND (status = 1 OR user_id = #{viewer})
  AND (
      create_time > #{createTime}
      OR (create_time = #{createTime} AND comment_id > #{commentId})
  )

SELECT , ru.nickname AS reply_to_nickname, LEFT(p.content, 120) AS reply_to_content, EXISTS ( SELECT 1 FROM blog_comment r WHERE r.parent_id = c.comment_id AND r.article_id = c.article_id ) AS has_children FROM blog_comment c JOIN blog_article a ON a.article_id = c.article_id JOIN sys_user u ON u.user_id = c.user_id LEFT JOIN blog_comment p ON p.comment_id = c.parent_id AND p.article_id = c.article_id LEFT JOIN sys_user ru ON ru.user_id = p.user_id
AND a.author_id = #{author}
AND c.parent_id IS NULL
AND c.parent_id = #{parent}
ORDER BY c.create_time DESC, c.comment_id DESC

SELECT c.* FROM blog_comment c
SELECT , ru.nickname AS reply_to_nickname, LEFT(p.content, 120) AS reply_to_content FROM blog_comment c JOIN sys_user u ON u.user_id = c.user_id JOIN blog_article a ON a.article_id = c.article_id LEFT JOIN blog_comment p ON p.comment_id = c.parent_id AND p.article_id = c.article_id LEFT JOIN sys_user ru ON ru.user_id = p.user_id
WHERE c.comment_id = #{id}
AND EXISTS ( SELECT 1 FROM blog_article s WHERE s.article_id = c.article_id AND s.author_id = #{author} )
AND c.user_id = #{user}
