UPDATE blog_comment c
SET c.status = #{comment.status}
WHERE c.comment_id = #{comment.commentId}

    AND EXISTS (
        SELECT 1
        FROM blog_article a
        WHERE a.article_id = c.article_id
          AND a.author_id = #{author}
    )


    AND c.user_id = #{user}
